// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address nonOwner, uint256 value, bytes calldata data) public {
        vm.assume(nonOwner != address(0) && nonOwner != c.Owner());
        vm.assume(value > 0);
        vm.deal(nonOwner, value);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(nonOwner);
        try c.Command{value: value}(address(this), data) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertEq(address(c).balance, balanceBefore, "balance must not change");
        }
    }
}
